#include <string>
#include <vector>

// The average of the values, or 0.0 for an empty vector.
double average(const std::vector<int>& values)
{
    if (values.empty())
    {
        return 0.0;
    }
    long long total{ 0 };
    for (int v : values) total += v;
    return static_cast<double>(total) / static_cast<double>(values.size());
}

// The last character of the text, or '?' if the text is empty.
char lastChar(const std::string& text)
{
    return text.empty() ? '?' : text.back();
}

// The whole number halfway between a and b (rounded towards a), for any two ints with a <= b.
int midpoint(int a, int b)
{
    return a + (b - a) / 2;
}

unitTests:
#include <limits>
TEST("average") { CHECK_NEAR(average({ 1, 2 }), 1.5, 1e-12); CHECK_NEAR(average({ 10 }), 10.0, 1e-12); CHECK_NEAR(average({}), 0.0, 1e-12); }
TEST("lastChar") { CHECK_EQ(lastChar("hello"), 'o'); CHECK_EQ(lastChar("x"), 'x'); CHECK_EQ(lastChar(""), '?'); }
TEST("midpoint of ordinary numbers") { CHECK_EQ(midpoint(2, 8), 5); CHECK_EQ(midpoint(3, 4), 3); CHECK_EQ(midpoint(7, 7), 7); }
TEST("midpoint of very large numbers must not overflow") { const int big{ std::numeric_limits<int>::max() }; CHECK_EQ(midpoint(big - 2, big), big - 1); CHECK_EQ(midpoint(big, big), big); CHECK_EQ(midpoint(2000000000, 2100000000), 2050000000); }

